SHOW DATABASES;
SHOW SCHEMAS;
SHOW DATABASES LIKE 'test%';
SHOW DATABASES WHERE `Database` LIKE 'test%';
SHOW TABLES;
SHOW FULL TABLES;
SHOW TABLES FROM mydb;
SHOW TABLES IN mydb LIKE 'user%';
SHOW COLUMNS FROM mytable;
SHOW FULL COLUMNS FROM mytable FROM mydb;
SHOW EXTENDED FULL COLUMNS FROM mytable WHERE Field LIKE 'id%';
SHOW CREATE TABLE mytable;
SHOW CREATE DATABASE mydb;
SHOW CREATE SCHEMA mydb;
SHOW CREATE VIEW myview;
SHOW CREATE EVENT myevent;
SHOW CREATE FUNCTION myfunc;
SHOW CREATE PROCEDURE myproc;
SHOW CREATE TRIGGER mytrigger;
SHOW CREATE USER 'root'@'localhost';
SHOW INDEX FROM mytable;
SHOW INDEXES FROM mytable FROM mydb;
SHOW KEYS FROM mytable WHERE Non_unique = 0;
SHOW GRANTS;
SHOW GRANTS FOR 'root'@'localhost';
SHOW GRANTS FOR 'someuser' USING 'somerole';
SHOW GRANTS FOR CURRENT_USER;
SHOW ENGINE innodb STATUS;
SHOW ENGINE innodb MUTEX;
SHOW ENGINES;
SHOW STORAGE ENGINES;
SHOW ERRORS;
SHOW ERRORS LIMIT 10;
SHOW WARNINGS;
SHOW WARNINGS LIMIT 5;
SHOW COUNT(*) ERRORS;
SHOW COUNT(*) WARNINGS;
SHOW EVENTS;
SHOW EVENTS FROM mydb LIKE 'my%';
SHOW FUNCTION CODE myfunc;
SHOW FUNCTION STATUS LIKE 'my%';
SHOW PROCEDURE CODE myproc;
SHOW PROCEDURE STATUS WHERE Db = 'mydb';
SHOW PROCESSLIST;
SHOW FULL PROCESSLIST;
SHOW PROFILE;
SHOW PROFILE CPU FOR QUERY 1;
SHOW PROFILE ALL FOR QUERY 1 OFFSET 1 LIMIT 5;
SHOW PROFILES;
SHOW OPEN TABLES;
SHOW OPEN TABLES FROM mydb LIKE 'my%';
SHOW PLUGINS;
SHOW PRIVILEGES;
SHOW STATUS;
SHOW GLOBAL STATUS;
SHOW SESSION STATUS LIKE 'Threads%';
SHOW VARIABLES;
SHOW GLOBAL VARIABLES LIKE 'version%';
SHOW SESSION VARIABLES WHERE Value > 0;
SHOW TABLE STATUS;
SHOW TABLE STATUS FROM mydb LIKE 'my%';
SHOW TRIGGERS;
SHOW TRIGGERS FROM mydb WHERE `Trigger` LIKE 'my%';
SHOW CHARACTER SET;
SHOW CHARACTER SET LIKE 'utf8%';
SHOW CHARSET;
SHOW COLLATION;
SHOW COLLATION LIKE 'utf8%';
SHOW BINARY LOGS;
SHOW MASTER LOGS;
SHOW BINARY LOG STATUS;
SHOW MASTER STATUS;
